// ─── File: src/main/java/com/bank/capability/model/Account.java ───
// ABSTRACT CLASS: shared state + constructor + template method
package com.bank.capability.model;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public abstract class Account {
    // ═══ SHARED STATE — why abstract class, not interface ═══
    private final String accountId;
    protected BigDecimal balance;
    private final List<String> auditLog = new ArrayList<>();

    // ═══ CONSTRUCTOR — interfaces cannot have constructors ═══
    protected Account(String accountId, BigDecimal initialBalance) {
        this.accountId = accountId;
        this.balance = initialBalance;
        auditLog.add("OPENED with Rs." + initialBalance);
    }

    // ═══ CONCRETE shared method — inherited by ALL subclasses ═══
    public void deposit(BigDecimal amount) {
        if (amount.signum() <= 0) throw new IllegalArgumentException("Must be positive");
        balance = balance.add(amount);
        auditLog.add("CREDIT Rs." + amount);
    }

    public void withdraw(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient balance");
        balance = balance.subtract(amount);
        auditLog.add("DEBIT Rs." + amount);
    }

    // ═══ ABSTRACT method — subclass MUST implement ═══
    public abstract BigDecimal calculateInterest();
    public abstract String getAccountType();

    // ═══ TEMPLATE METHOD — calls abstract method (filled by subclass) ═══
    public final void processMonthEnd() {
        BigDecimal interest = calculateInterest();  // subclass decides!
        if (interest.signum() > 0) {
            deposit(interest);
            auditLog.add("INTEREST CREDITED Rs." + interest);
        }
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public List<String> getAuditLog() { return Collections.unmodifiableList(auditLog); }

    @Override
    public String toString() {
        return getAccountType() + "[" + accountId + "] Rs." + balance;
    }
}
