// ─── File: src/main/java/com/bank/capability/model/SavingsAccount.java ───
// Extends abstract class + implements 2 interfaces
package com.bank.capability.model;

import com.bank.capability.capability.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

public class SavingsAccount extends Account implements Auditable, Notifiable {
    // Extends ONE class (Account). Implements TWO interfaces (Auditable, Notifiable).
    // NOT Transferable — savings can't transfer directly.

    private final BigDecimal annualRate;

    public SavingsAccount(String accountId, BigDecimal balance, BigDecimal rate) {
        super(accountId, balance);  // calls abstract class constructor!
        this.annualRate = rate;
    }

    @Override
    public BigDecimal calculateInterest() {
        return getBalance().multiply(annualRate)
            .divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP);
    }

    @Override
    public String getAccountType() { return "SAVINGS"; }

    // ═══ Auditable implementation ═══
    @Override
    public List<String> generateAuditReport() {
        return getAuditLog();  // uses shared state from abstract class!
    }

    // ═══ Notifiable implementation ═══
    @Override
    public void sendNotification(String message) {
        System.out.println("[SMS to " + getAccountId() + "] " + message);
    }
}
