// Extends abstract class + implements ALL THREE interfaces
package com.bank.capability.model;

import com.bank.capability.capability.*;
import java.math.BigDecimal;
import java.util.List;

public class CurrentAccount extends Account implements Auditable, Notifiable, Transferable {
    // Extends ONE class. Implements THREE interfaces — multiple inheritance of behavior!

    public CurrentAccount(String accountId, BigDecimal balance) {
        super(accountId, balance);
    }

    @Override
    public BigDecimal calculateInterest() { return BigDecimal.ZERO; }

    @Override
    public String getAccountType() { return "CURRENT"; }

    @Override
    public List<String> generateAuditReport() { return getAuditLog(); }

    @Override
    public void sendNotification(String message) {
        System.out.println("[Email to " + getAccountId() + "] " + message);
    }

    // ═══ Transferable — only CurrentAccount has this capability! ═══
    @Override
    public String transferTo(String targetAccountId, BigDecimal amount) {
        withdraw(amount);  // uses abstract class's shared method
        return "Transferred Rs." + amount + " from " + getAccountId() + " to " + targetAccountId;
    }
}
