// ─── File: src/main/java/com/bank/capability/service/AccountProcessorService.java ───
package com.bank.capability.service;

import com.bank.capability.capability.*;
import com.bank.capability.model.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@Slf4j
public class AccountProcessorService {

    public Map<String, Object> demonstrateChoices() {
        Map<String, Object> report = new LinkedHashMap<>();

        SavingsAccount savings = new SavingsAccount("SAV2001", new BigDecimal("120000"), new BigDecimal("0.04"));
        CurrentAccount current = new CurrentAccount("CUR3001", new BigDecimal("500000"));

        // ═══ ABSTRACT CLASS: shared state + template method ═══
        savings.processMonthEnd();  // template calls savings.calculateInterest() → 400
        current.processMonthEnd();  // template calls current.calculateInterest() → 0
        report.put("abstract_class_template", "Savings interest: Rs." + savings.getBalance()
            + " | Current: Rs." + current.getBalance());

        // ═══ INTERFACE: capability-based processing ═══
        List<Account> allAccounts = List.of(savings, current);

        // Process Auditable accounts:
        allAccounts.stream()
            .filter(a -> a instanceof Auditable)
            .forEach(a -> {
                String summary = ((Auditable) a).getAuditSummary();
                report.put("auditable_" + a.getAccountId(), summary);
            });

        // Process Transferable accounts (only CurrentAccount):
        allAccounts.stream()
            .filter(a -> a instanceof Transferable)
            .forEach(a -> {
                String result = ((Transferable) a).transferTo("SAV2001", new BigDecimal("10000"));
                report.put("transferable_" + a.getAccountId(), result);
            });

        // ═══ WHY INTERFACE for capabilities ═══
        report.put("why_interface", "Auditable + Notifiable + Transferable are CAPABILITIES. " +
            "Multiple interfaces allowed. Not all accounts have all capabilities.");
        report.put("why_abstract_class", "Account has SHARED STATE (balance, auditLog) + " +
            "CONSTRUCTOR + TEMPLATE METHOD. Interface cannot have these.");

        return report;
    }
}
