// ─── File: src/test/java/com/bank/capability/AbstractVsInterfaceTest.java ───
package com.bank.capability;

import com.bank.capability.capability.*;
import com.bank.capability.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class AbstractVsInterfaceTest {

    // ═══ ABSTRACT CLASS: shared state via constructor ═══
    @Test
    void abstractClass_sharedStateAndConstructor() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("100000"), new BigDecimal("0.04"));
        assertThat(sa.getBalance()).isEqualByComparingTo("100000");
        assertThat(sa.getAccountId()).isEqualTo("SAV001");
        // State initialized via constructor — interface CANNOT do this.
    }

    // ═══ ABSTRACT CLASS: template method calls abstract method ═══
    @Test
    void abstractClass_templateMethodPattern() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        sa.processMonthEnd();  // template: calls calculateInterest() → deposit()
        // 120000 × 4% / 12 = 400 interest → balance = 120400
        assertThat(sa.getBalance()).isEqualByComparingTo("120400");
        assertThat(sa.getAuditLog()).anyMatch(log -> log.contains("INTEREST"));
    }

    // ═══ INTERFACE: multiple inheritance of behavior ═══
    @Test
    void interface_multipleInheritance() {
        CurrentAccount ca = new CurrentAccount("CUR001", new BigDecimal("500000"));
        // Implements THREE interfaces:
        assertThat(ca).isInstanceOf(Auditable.class);
        assertThat(ca).isInstanceOf(Notifiable.class);
        assertThat(ca).isInstanceOf(Transferable.class);
        // Cannot extend two abstract classes — but CAN implement multiple interfaces!
    }

    // ═══ INTERFACE: not all types have all capabilities ═══
    @Test
    void interface_selectiveCapabilities() {
        SavingsAccount sa = new SavingsAccount("SAV001", BigDecimal.ZERO, new BigDecimal("0.04"));
        assertThat(sa).isInstanceOf(Auditable.class);      // ✅ has audit
        assertThat(sa).isInstanceOf(Notifiable.class);      // ✅ has notifications
        assertThat(sa).isNotInstanceOf(Transferable.class); // ❌ NO transfer capability!
        // Savings account is Auditable + Notifiable but NOT Transferable.
    }

    // ═══ INTERFACE: default method provides shared behavior without state ═══
    @Test
    void interface_defaultMethod() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("10000"), new BigDecimal("0.04"));
        sa.deposit(new BigDecimal("5000"));
        String summary = sa.getAuditSummary();  // default method on Auditable interface
        assertThat(summary).contains("Audit:").contains("entries");
    }

    // ═══ THE CHOICE: when does it matter? ═══
    @Test
    void whenChoiceMatters() {
        // Need shared mutable fields (balance, auditLog)? → abstract class Account ✅
        // Need constructors to initialize state? → abstract class Account ✅
        // Need multiple capabilities on one class? → interfaces (Auditable, Notifiable) ✅
        // Need a class to participate in multiple type hierarchies? → interfaces ✅
        // Don't need state, just behavior contract? → interface with default methods ✅
        assertThat(true).isTrue();
    }

    // ═══ TRANSFERABLE only for CurrentAccount ═══
    @Test
    void transferableOnlyOnCurrentAccount() {
        CurrentAccount ca = new CurrentAccount("CUR001", new BigDecimal("500000"));
        String result = ca.transferTo("SAV001", new BigDecimal("50000"));
        assertThat(result).contains("Transferred");
        assertThat(ca.getBalance()).isEqualByComparingTo("450000");
    }
}
